    return sum(1 for c in s if c in ''aeiouAEIOU'')', '[{"input":"\"hello\"","output":"2"},{"input":"\"python\"","output":"1"}]', NULL, NULL, '', 'approved', 'system', TRUE, 'library_ai_coding', '2025-12-17T23:42:52.321Z', '2025-12-17T23:42:52.727Z', TRUE, FALSE, NULL, NULL, TRUE, 'cmjanptpd0029w900o8pp2v17', NULL
